li.script:
document.addEventListener('DOMContentLoaded', function() {
    // Seleccionar el botón de login (utilizando selector más genérico)
    var loginBtn = document.querySelector('a[href="/web/login"]');
    if (!loginBtn) return;

    // Animación al pasar el mouse
    loginBtn.addEventListener('mouseenter', function() {
        // Efecto 3D y sombra
        this.style.transform = 'translateY(-3px)';
        this.style.boxShadow = '0 8px 15px rgba(255,145,77,0.35)';
    });

    loginBtn.addEventListener('mouseleave', function() {
        // Restaurar estilo normal
        this.style.transform = 'translateY(0)';
        this.style.boxShadow = '0 4px 10px rgba(255,145,77,0.2)';
    });

    // Animar indicador de sesión si existe
    var sessionIndicator = loginBtn.querySelector('[class*="position-absolute"]');
    if (sessionIndicator) {
        function pulseIndicator() {
            sessionIndicator.style.transform = 'scale(1.2)';
            sessionIndicator.style.opacity = '1';
            sessionIndicator.style.transition = 'all 0.5s ease';

            setTimeout(function() {
                sessionIndicator.style.transform = 'scale(1)';
                sessionIndicator.style.opacity = '0.9';
                sessionIndicator.style.transition = 'all 0.5s ease';
            }, 600);
        }

        // Iniciar la animación
        setInterval(pulseIndicator, 2000);
    }
});
